@OptIn(ExperimentalMaterial3AdaptiveApi::class)
NavigableListDetailPaneScaffold(
    navigator = navigator,
    listPane = {
        AnimatedPane {
            val reviewed = items.count { it.id in verdicts }
            LazyColumn {
                item(key = "progress") {
                    Column(
                        modifier = Modifier.padding(MonarchTheme.spacing.space4),
                        verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
                    ) {
                        MonarchText(text = "$reviewed of ${items.size} reviewed", style = MonarchTextStyle.Caption)
                        MonarchProgress(
                            progress = reviewed.toFloat() / items.size,
                            label = "$reviewed of ${items.size} reviewed",
                        )
                    }
                }
                items(items = items, key = { it.id }) { item ->
                    MonarchListRow(
                        headlineContent = { Text(item.title) },
                        trailingContent = {
                            MonarchText(
                                text = when (verdicts[item.id]) {
                                    "pass" -> "Pass"
                                    "fail" -> "Fail"
                                    else -> "Not reviewed"
                                },
                                style = MonarchTextStyle.Caption,
                                color = MonarchTheme.colors.textMuted,
                            )
                        },
                        onClick = {
                            current = item.id
                            scope.launch { navigator.navigateTo(ListDetailPaneScaffoldRole.Detail, item.id) }
                        },
                        selected = item.id == current,
                    )
                }
            }
        }
    },
    detailPane = {
        AnimatedPane {
            val index = items.indexOfFirst { it.id == current }.coerceAtLeast(0)
            val item = items[index]
            val itemScores = scores[item.id].orEmpty()
            val total = itemScores.values.sum()
            val max = rubric.sumOf { it.scale }
            Column(
                modifier = Modifier.verticalScroll(rememberScrollState()).padding(MonarchTheme.spacing.space4),
                verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
            ) {
                MonarchText(text = "${index + 1} of ${items.size}", style = MonarchTextStyle.Caption)
                MonarchText(text = item.title, style = MonarchTextStyle.Heading)
                MonarchText(text = item.meta, style = MonarchTextStyle.Caption)
                FlowRow(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                    MonarchButton(
                        text = "Previous",
                        onClick = { current = items[index - 1].id },
                        size = MonarchButtonSize.Sm,
                        enabled = index > 0,
                    )
                    MonarchButton(
                        text = "Next",
                        onClick = { current = items[index + 1].id },
                        size = MonarchButtonSize.Sm,
                        enabled = index < items.lastIndex,
                    )
                }
                MonarchCard {
                    MonarchText(text = "Prompt".uppercase(), style = MonarchTextStyle.Label, color = MonarchTheme.colors.textMuted)
                    MonarchText(text = item.prompt)
                }
                MonarchCard(tone = MonarchTone.Ai) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        MonarchText(text = "Output".uppercase(), style = MonarchTextStyle.Label, color = MonarchTheme.colors.textMuted)
                        MonarchAiGeneratedBadge(size = MonarchAiGeneratedBadgeSize.Sm)
                    }
                    MonarchAiMarkdown(text = item.output)
                }
                item.reference?.let { reference ->
                    MonarchCard {
                        MonarchText(text = "Expected".uppercase(), style = MonarchTextStyle.Label, color = MonarchTheme.colors.textMuted)
                        MonarchText(text = reference)
                    }
                }
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    MonarchText(text = "Rubric".uppercase(), style = MonarchTextStyle.Label, color = MonarchTheme.colors.textMuted)
                    MonarchText(text = "Score $total / $max", style = MonarchTextStyle.BodyStrong)
                }
                rubric.forEach { criterion ->
                    Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1)) {
                        MonarchText(text = criterion.label, style = MonarchTextStyle.Label)
                        criterion.description?.let { MonarchText(text = it, style = MonarchTextStyle.Caption) }
                        MonarchRatingPicker(
                            value = itemScores[criterion.id],
                            onValueChange = { score ->
                                val next = if (score == null) {
                                    itemScores - criterion.id
                                } else {
                                    itemScores + (criterion.id to score)
                                }
                                scores = scores + (item.id to next)
                            },
                            options = MonarchRatingOption.range(1, criterion.scale),
                            clearable = true,
                        )
                    }
                }
                MonarchTextField(
                    value = notes[item.id].orEmpty(),
                    onValueChange = { notes = notes + (item.id to it) },
                    label = "Notes",
                    singleLine = false,
                )
                MonarchText(text = "Verdict", style = MonarchTextStyle.Label)
                Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                    listOf("pass" to "Pass", "fail" to "Fail").forEach { (value, label) ->
                        MonarchButton(
                            text = label,
                            onClick = { verdicts = verdicts + (item.id to value) },
                            variant = if (verdicts[item.id] == value) MonarchButtonVariant.Primary else MonarchButtonVariant.Secondary,
                            size = MonarchButtonSize.Sm,
                            leadingIcon = { MonarchIcon(if (value == "pass") SampleIcons.Check else SampleIcons.Close, contentDescription = null) },
                        )
                    }
                }
                MonarchButton(
                    text = "Submit reviews",
                    onClick = { /* Send the reviews to the evaluation service. */ },
                    variant = MonarchButtonVariant.Primary,
                    enabled = verdicts.size == items.size,
                )
            }
        }
    },
)

