Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
    MonarchText(text = "Score ${(accuracy ?: 0) + (tone ?: 0)} / 8", style = MonarchTextStyle.BodyStrong)
    MonarchText(text = "Facts match the source or reference.", style = MonarchTextStyle.Caption)
    MonarchRatingPicker(value = accuracy, onValueChange = { accuracy = it }, label = "Accuracy")
    MonarchRatingPicker(
        value = tone,
        onValueChange = { tone = it },
        label = "Tone",
        options = MonarchRatingOption.range(1, 3),
    )
    MonarchTextField(value = notes, onValueChange = { notes = it }, label = "Notes", singleLine = false)
    MonarchText(text = "Verdict", style = MonarchTextStyle.Label)
    MonarchSegmentedControl(fillWidth = true) {
        listOf("pass" to "Pass", "fail" to "Fail").forEach { (value, label) ->
            Segment(selected = verdict == value, onClick = { verdict = value }, label = label)
        }
    }
}
